import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(__dirname, "..");
const outDir = path.join(rootDir, "plugin", "dist");
const outFile = path.join(outDir, "plugin.mjs");
const manifestPath = path.join(rootDir, "public", "paybox-plugin.json");

fs.mkdirSync(outDir, { recursive: true });

const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));

const pluginSource = `/**
 * sCrow PayBox Plugin Bundle (ESM)
 * Auto-generated by scripts/build-plugin.mjs
 */

export const SCROW_PROGRAM_ID = "SCrow11111111111111111111111111111111111111";
export const SCROW_PROTOCOL_TREASURY = "TrsrySCrow111111111111111111111111111111111";
export const PROTOCOL_FEE_BPS = 75;
export const BPS_DENOMINATOR = 10000;
export const MAX_REVISION_ATTEMPTS = 3;
export const ESCROW_PDA_RENT_SOL = 0.00373632;

export const payboxPluginManifest = ${JSON.stringify(manifest, null, 2)};

export function calculatePayoutBreakdown(amountSol) {
  const lamports = Math.round(Number(amountSol) * 1_000_000_000);
  const feeLamports = Math.floor((lamports * PROTOCOL_FEE_BPS) / BPS_DENOMINATOR);
  const recipientLamports = lamports - feeLamports;
  return {
    totalSol: Number(amountSol),
    protocolFeeSol: Number((feeLamports / 1_000_000_000).toFixed(6)),
    recipientPayoutSol: Number((recipientLamports / 1_000_000_000).toFixed(6)),
    reclaimedRentSol: ESCROW_PDA_RENT_SOL,
  };
}

export function createScrowPayBoxPlugin(config = {}) {
  const endpoint = config.endpoint || payboxPluginManifest.mcp.endpoint;
  return {
    manifest: payboxPluginManifest,
    tools: payboxPluginManifest.mcp.tools,
    async invokeTool(name, args = {}) {
      const response = await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: Date.now(),
          method: "tools/call",
          params: { name, arguments: args },
        }),
      });
      if (!response.ok) {
        throw new Error(\`sCrow MCP tool call failed: \${response.statusText}\`);
      }
      const payload = await response.json();
      if (payload.error) {
        throw new Error(payload.error.message || "sCrow MCP error");
      }
      return payload.result?.structuredContent ?? payload.result;
    },
  };
}

export default createScrowPayBoxPlugin;
`;

fs.writeFileSync(outFile, pluginSource, "utf8");
console.log("✓ Built PayBox plugin artifact:", path.relative(rootDir, outFile));
